// END GENERATED C1S13_HARNESS_DETAIL

const generatedAny = c1s13HarnessCanvasGenerated as unknown as {
  harnessSummaryGenerated?: HarnessSummary;
  harnessScenarioDetailGenerated?: readonly ScenarioRow[];
};
const summary: HarnessSummary = generatedAny.harnessSummaryGenerated ?? {
  llmModel: null,
  passCount: 0,
  scenarioCount: 0,
  scenarioEstimatedCostUsd: null,
  benchmarkReportPath: '',
};
const rows: readonly ScenarioRow[] = generatedAny.harnessScenarioDetailGenerated ?? [];

function pct(value: number | null): string {
  if (typeof value !== 'number' || Number.isNaN(value)) return 'n/a';
  return `${Math.round(value * 100)}%`;
}

function toneForOk(ok: boolean): 'success' | 'danger' {
  return ok ? 'success' : 'danger';
}

function renderExpectedRouteLabel(
  check: { expected: string; expected_route_candidates?: readonly string[] },
): string {
  const candidates = check.expected_route_candidates || [];
  if (candidates.length) return candidates.join('\n');
  return `(unresolved from token: ${check.expected})`;
}

function renderViolationRows(row: ScenarioRow): string[] {
  if (!row.violations?.length) return [];
  return row.violations.map((violation) => {
    if (violation === 'missing_expected_route_hit') {
      const missing = (row.missing_expected_route_substrings || []).join(', ') || 'unknown';
      return `missing_expected_route_hit: missing route expectations -> ${missing}`;
    }
    if (violation === 'missing_expected_unit_id_hit') {
      return `missing_expected_unit_id_hit: one or more expected entity/unit routes were not retrieved`;
    }
    if (violation === 'context_support_below_threshold') {
      return `context_support_below_threshold: got ${pct(row.context_support_ratio)} support`;
    }
    return violation;
  });
}

export default function C1S13BreadcrumbBenchmarkReviewCanvas() {
  const [openMap, setOpenMap] = useCanvasState<Record<string, boolean>>('c1s13_query_open_map', {});

  const passRate =
    summary.scenarioCount > 0 ? Math.round((summary.passCount / summary.scenarioCount) * 100) : 0;

  return (
    <Stack gap={16}>
      <H1>C1S13 Breadcrumb Retrieval Review</H1>
      <Text tone="secondary">
        Session recap benchmark review with per-query deep-dive accordions.
      </Text>

      <Grid columns={4} gap={12}>
        <Stat label="Pass" value={`${summary.passCount}/${summary.scenarioCount}`} />
        <Stat label="Pass Rate" value={`${passRate}%`} />
        <Stat label="LLM Model" value={summary.llmModel || 'n/a'} />
        <Stat
          label="Cost (run)"
          value={
            typeof summary.scenarioEstimatedCostUsd === 'number'
              ? `$${summary.scenarioEstimatedCostUsd.toFixed(4)}`
              : 'n/a'
          }
        />
      </Grid>

      <Card>
        <CardHeader>Inputs</CardHeader>
        <CardBody>
          <Stack gap={6}>
            <Text>
              Source recap: <Code>{sourceRecap}</Code>
            </Text>
            <Text>
              Gold: <Code>{benchmarkGold}</Code>
            </Text>
            <Text>
              Report template: <Code>{benchmarkReport}</Code>
            </Text>
            {summary.benchmarkReportPath ? (
              <Text>
                Last generated report: <Code>{summary.benchmarkReportPath}</Code>
              </Text>
            ) : null}
          </Stack>
        </CardBody>
      </Card>

      <H2>Query Deep Dive</H2>
      {rows.length === 0 ? (
        <Card>
          <CardHeader>No generated data yet</CardHeader>
          <CardBody>
            <Text>
              Run <Code>breadcrumb_query_run</Code> with C1S13 gold, then run <Code>c1s13_benchmark_canvas_emit</Code>{' '}
              to populate this canvas.
            </Text>
          </CardBody>
        </Card>
      ) : null}

      {rows.map((row) => (
        <Card
          key={row.id}
          collapsible
          open={openMap[row.id] ?? false}
          onOpenChange={(open) => setOpenMap((prev) => ({ ...prev, [row.id]: open }))}
        >
          <CardHeader
            trailing={
              <Row gap={8} align="center">
                <Pill tone={toneForOk(row.ok)}>{row.ok ? 'PASS' : 'FAIL'}</Pill>
                <Text tone="secondary" size="small">
                  context {pct(row.context_support_ratio)} / llm {pct(row.llm_context_support_ratio)}
                </Text>
              </Row>
            }
          >
            {row.id}
          </CardHeader>
          <CardBody>
            <Stack gap={10}>
              <Text>
                <Text as="span" weight="semibold">
                  Question:
                </Text>{' '}
                {row.question}
              </Text>
              <Text>
                <Text as="span" weight="semibold">
                  Expected:
                </Text>{' '}
                {row.expected_answer}
              </Text>
              <Text>
                <Text as="span" weight="semibold">
                  LLM answer preview:
                </Text>{' '}
                {row.llm_answer_preview || 'n/a'}
              </Text>
              <Text>
                <Text as="span" weight="semibold">
                  Semantic verdict:
                </Text>{' '}
                {row.llm_semantic_verdict || 'n/a'}
              </Text>
              {typeof row.benchmark_ok_raw === 'boolean' && row.benchmark_ok_raw !== row.ok ? (
                <Text tone="secondary" size="small">
                  Raw benchmark ok: {row.benchmark_ok_raw ? 'PASS' : 'FAIL'} (canvas reconciles route violations with resolved route evidence)
                </Text>
              ) : null}
              <Table
                headers={['Must-hit token', 'Seen in retrieved context', 'Seen in LLM answer']}
                rows={(row.keyword_rows || []).map((k) => [
                  k.token,
                  k.in_retrieved_context_ci ? 'yes' : 'no',
                  k.in_llm_answer_ci ? 'yes' : 'no',
                ])}
                rowTone={(row.keyword_rows || []).map((k) =>
                  k.in_retrieved_context_ci ? 'success' : 'warning',
                )}
                emptyMessage="No must-hit tokens listed."
              />
              <Table
                headers={['Expected route(s)', 'Matched?', 'Retrieved route evidence']}
                rows={(row.route_checks || []).map((chk) => [
                  renderExpectedRouteLabel(chk),
                  chk.matched ? 'yes' : 'no',
                  (chk.matched_routes || []).join('\n') || 'none',
                ])}
                rowTone={(row.route_checks || []).map((chk) => (chk.matched ? 'success' : 'danger'))}
                emptyMessage="No expected routes listed."
              />
              <Text tone="secondary" size="small">
                Missing expected routes: {(row.missing_expected_route_substrings || []).join(', ') || 'none'}
              </Text>
              <Card collapsible defaultOpen={false}>
                <CardHeader>Retrieved context (promoted lexical)</CardHeader>
                <CardBody>
                  <Text>{row.lexical_hit_context_promoted || 'n/a'}</Text>
                </CardBody>
              </Card>
              <Card collapsible defaultOpen={false}>
                <CardHeader>Retrieved routes</CardHeader>
                <CardBody>
                  <Table
                    headers={['Route']}
                    rows={(row.retrieved_route_values || []).map((route) => [route])}
                    emptyMessage="No retrieved routes."
                  />
                </CardBody>
              </Card>
              <Card collapsible defaultOpen={false}>
                <CardHeader>LLM user message</CardHeader>
                <CardBody>
                  <Text>{row.llm_user_message || 'n/a'}</Text>
                </CardBody>
              </Card>
              <Card collapsible defaultOpen={false}>
                <CardHeader>Top retrieval hits</CardHeader>
                <CardBody>
                  <Table
                    headers={['Unit', 'Lines', 'Score', 'Routes']}
                    rows={(row.hit_rows || []).map((h) => [
                      h.unit_id,
                      h.line_span,
                      String(h.score),
                      (h.routes || []).join('\n'),
                    ])}
                    emptyMessage="No hit rows found."
                  />
                </CardBody>
              </Card>
              {row.violations.length ? (
                <Card>
                  <CardHeader>Violations</CardHeader>
                  <CardBody>
                    <Table
                      headers={['Violation']}
                      rows={renderViolationRows(row).map((v) => [v])}
                      rowTone={renderViolationRows(row).map(() => 'danger')}
                    />
                  </CardBody>
                </Card>
              ) : null}
            </Stack>
          </CardBody>
        </Card>
      ))}
    </Stack>
  );
}
